"""Regenerate the standalone GitHub Pages guide with Python 3."""
from pathlib import Path
import json
from html import escape as e

root = Path(__file__).parent
data = json.loads((root / 'data.json').read_text())
funding = 'https://www.fppc.ca.gov/search-filings/top-10-contributors-list/november-2026-general-election/'
def link(url, label):
    return f'<a href="{e(url)}">{e(label)} ↗</a>'
cards = []
for p in data:
    url = f'https://voterguide.sos.ca.gov/propositions/{p["n"]}/'
    extra = link(url + p['extra'], 'Additional analysis / arguments') if p.get('extra') else ''
    moneycite = link(funding, 'FPPC disclosure') if not p['money'].startswith('No donor') else ''
    cards.append(f'''<article id="prop-{p['n']}" data-topic="{e(p['topic'])}">
      <header class="measure-head"><div class="number"><span>PROP</span>{p['n']:02}</div><div><p class="eyebrow">{e(p['topic'])}</p><h2>{e(p['title'])}</h2><p class="issue">{e(p['issue'])}</p></div></header>
      <div class="votes"><section><h3><span class="vote-symbol">+</span> A YES vote</h3><p>{e(p['yes'])}</p></section><section><h3><span class="vote-symbol">−</span> A NO vote</h3><p>{e(p['no'])}</p></section></div>
      <div class="debate"><section><h3>The case for</h3><p>{e(p['for'])}</p></section><section><h3>The case against</h3><p>{e(p['against'])}</p></section></div>
      <p class="cost"><strong>Public cost & revenue</strong> {e(p['cost'])}</p>
      <section class="reality"><h3>Read past the pitch <span>Editorial assessment</span></h3><p>{e(p['check'])}</p></section>
      <div class="debate bottom"><section><h3>Money & interests</h3><p>{e(p['money'])} {moneycite}</p><p class="secondary">{e(p['interest'])}</p></section><section><h3>The values in tension</h3><p>{e(p['values'])}</p><p class="secondary">A question to weigh, not a voting recommendation.</p></section></div>
      <footer class="sources">Sources for provisions, estimates & campaign positions: {link(url, 'Official voter guide')} {extra}<a class="top" href="#measures">Back to measures ↑</a></footer>
    </article>''')
nav = ''.join(f'<a href="#prop-{p["n"]}" aria-label="Proposition {p["n"]}">{p["n"]}</a>' for p in data)
html = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>California, considered · 2026 Proposition Guide</title><meta name="description" content="An independent, sourced guide to California’s 14 November 2026 propositions: vote meanings, arguments, funding, tradeoffs and claims to examine."><meta name="theme-color" content="#173b35"><link rel="stylesheet" href="style.css"><script src="guide.js" defer></script></head>
<body><a class="skip" href="#measures">Skip to propositions</a><header class="masthead"><a href="#" class="brand">CA <span>/</span> CONSIDERED</a><div>INDEPENDENT VOTER FIELD GUIDE <span class="edition">· NOVEMBER 2026</span></div><button id="print" type="button">Print guide ↗</button></header>
<main><section class="hero"><div><p class="eyebrow">CALIFORNIA · NOVEMBER 3, 2026</p><h1>A little less spin.<br>A lot more <em>context.</em></h1><p class="intro">Fourteen propositions. Real tradeoffs. Follow the money, examine the arguments, and understand what your vote changes.</p><a class="start" href="#measures">Explore the ballot <span>↓</span></a></div><aside class="cover-note"><span class="sun" aria-hidden="true">✳</span><p>YOUR BALLOT,<br>YOUR JUDGMENT.</p><div>01—05<br>37—45</div><small>All statewide propositions<br>Research checked November 3, 2026</small></aside></section>
<section class="reading-note"><strong>How to read this guide</strong><p>Vote meanings and fiscal estimates come from the official guide. Campaign arguments are attributed, not adopted. “Read past the pitch” and interest assessments are editorial reasoning. Uncertain outcomes stay uncertain.</p><p>This guide does not infer your politics or score your alignment. Each measure presents competing values so you can make your own assessment. It covers statewide measures only and is not an official government publication.</p></section>
<section class="connection"><p class="eyebrow">READ THESE TOGETHER</p><h2>40 ↔ 41 ↔ 42</h2><div><p><strong>Three measures, one potential collision.</strong> Proposition 40 creates a wealth tax. Proposition 41 restricts spending-limit exemptions; Proposition 42 restricts new asset taxes and retroactivity.</p><p>The legislative analyst says that if 41 or 42 receives more Yes votes than 40, courts could find a conflict and prevent 40 from taking effect even if it passes. This is a possible legal outcome, not an automatic prediction. <a href="https://voterguide.sos.ca.gov/propositions/40/analysis.htm">Read the analysis ↗</a></p></div></section>
<section id="measures" class="ballot"><div class="section-title"><h2>The measures</h2><span>14 PROPOSITIONS / NO ENDORSEMENTS</span></div><nav class="jump" aria-label="Jump to proposition">NAVIGATE '''+nav+'''</nav><div class="tools"><label for="search">Find a measure<input type="search" id="search" placeholder="Search issue, number, or organization…"></label><label for="topic">Browse by topic<select id="topic"><option>All topics</option><option>Housing</option><option>Taxes &amp; budgets</option><option>Democracy</option><option>Health</option></select></label></div><p id="count" role="status" aria-live="polite">Showing all 14 measures</p><div id="cards">'''+''.join(cards)+'''</div><p id="empty" hidden>No measures match. Try another search or topic.</p></section>
<section class="method" id="method"><p class="eyebrow">SOURCES & LIMITS</p><h2>Evidence before certainty.</h2><div class="method-grid"><div><h3>Campaign claims are not findings</h3><p>The Secretary of State publishes arguments from advocates alongside independent analysis. Their presence in an official booklet does not validate them. This guide flags omissions and unsupported certainty rather than treating all disagreements as equally factual.</p><p>Supporter and opponent lists are selected examples, not exhaustive endorsements. “No argument submitted” does not mean no opposition exists. Fiscal estimates are forecasts, not guarantees.</p></div><div><h3>What the money tells us</h3><p>Donors shown are selected examples from FPPC disclosures checked November 3, 2026, not campaign totals. Lists have reporting thresholds. Transfers and committees covering multiple measures can overlap; do not add figures across measures. Missing figures do not mean zero fundraising.</p><p>Donations establish support, not motive or corruption. Interest assessments are explicitly labeled inferences. This is a dated research snapshot, not a live finance tracker.</p></div></div><div class="source-links"><a href="https://voterguide.sos.ca.gov/propositions">Official ballot & full texts ↗</a><a href="https://lao.ca.gov/BallotAnalysis/Propositions">Legislative Analyst’s Office ↗</a><a href="'''+funding+'''">FPPC campaign disclosures ↗</a><a href="https://powersearch.sos.ca.gov/">Search contribution filings ↗</a></div></section>
</main><footer class="page-footer"><span>CALIFORNIA, CONSIDERED.</span><p>Independent information. No recommended slate. No tracking.</p><a href="https://www.sos.ca.gov/elections">Official election information ↗</a></footer></body></html>'''
(root / 'index.html').write_text(html)
print(f'Built {len(data)} measures; {len(html):,} characters.')
